"""Run sentiment inference with the saved training-only TF-IDF vocabulary."""
import argparse
import json
import pickle
from pathlib import Path

import torch

from sentiment import SentimentMLP, clean_text


def load_model(model_dir):
    root = Path(model_dir)
    config = json.loads((root / "config.json").read_text(encoding="utf-8"))
    # This pickle is generated by our own training run; do not load untrusted pickles.
    with (root / "vectorizer.pkl").open("rb") as handle:
        vectorizer = pickle.load(handle)
    model = SentimentMLP(config["input_dim"], config["hidden_dim"], config["dropout"])
    model.load_state_dict(torch.load(root / "model.pt", map_location="cpu", weights_only=True))
    model.eval()
    return model, vectorizer, config


def predict(texts, model_dir="model"):
    normalized = [clean_text(text) for text in texts]
    if not normalized or any(not text for text in normalized):
        raise ValueError("Provide at least one nonempty review.")
    model, vectorizer, config = load_model(model_dir)
    matrix = vectorizer.transform(normalized)
    results = []
    with torch.inference_mode():
        for start in range(0, len(texts), 64):
            batch = matrix[start:start + 64]
            scores = torch.sigmoid(model(torch.from_numpy(batch.toarray()))).tolist()
            for offset, score in enumerate(scores):
                row = batch.getrow(offset)
                label = int(score >= config["threshold"])
                results.append({"text": texts[start + offset], "label": config["id2label"][str(label)],
                    "positive_score": score, "has_known_terms": bool(row.nnz),
                    "note": "Score is not calibrated; no known terms means the prediction is unreliable."})
    return results


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("texts", nargs="+")
    parser.add_argument("--model-dir", default="model")
    args = parser.parse_args()
    print(json.dumps(predict(args.texts, args.model_dir), indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
